public class Main {
    public static void main(String[] args) {
        System.out.println("Processing transaction queue (1 to 6):");

        for (int txId = 1; txId <= 6; txId++) {
            if (txId == 3) {
                System.out.println("Tx #" + txId + " is duplicate -> SKIPPING (continue)");
                continue;
            }
            if (txId == 5) {
                System.out.println("Tx #" + txId + " security alarm triggered -> STOPPING (break)");
                break;
            }
            System.out.println("Processed Tx #" + txId + " successfully.");
        }

        System.out.println("Queue processing halted.");
    }
}

