public class Main {
    public static void main(String[] args) {
        int[] txs = {50, -20, 100, -10, 999, 40};
        int total = 0;
        for (int i = 0; i < txs.length; i++) {
            int tx = txs[i];
            if (tx < 0) {
                System.out.println("Skipping negative amount: " + tx);
                continue;
            }
            if (tx == 999) {
                System.out.println("Fraud alert triggered! Halting.");
                break;
            }
            System.out.println("Processed: $" + tx);
            total += tx;
        }
        System.out.println("Total Clean Funds: $" + total);
    }
}

