public class Main {
    public static void main(String[] args) {
        for (int i = 1; i <= 12; i++) {
            if (i % 5 == 0) continue;
            System.out.print(i + " ");
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        int[] items = {10, 25, 42, 99, 15};
        for (int i = 0; i < items.length; i++) {
            System.out.println("Checking: " + items[i]);
            if (items[i] == 42) {
                System.out.println("Found target 42! Stopping search.");
                break;
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int[] numbers = {-5, 12, -3, 8, -1, 15, 20};
        int sum = 0;
        int count = 0;
        for (int i = 0; i < numbers.length; i++) {
            int n = numbers[i];
            if (n <= 0) continue;
            System.out.println("Added: " + n);
            sum += n;
            count++;
            if (count == 3) break;
        }
        System.out.println("Target reached. Total: " + sum);
    }
}

