public class Main {
    public static void main(String[] args) {
        int[] nums = {4, 6, 8, 9, 11, 12};
        for (int i = 0; i < nums.length; i++) {
            int n = nums[i];
            if (n == 11) {
                System.out.println("First prime found: 11");
                break;
            }
            System.out.println(n + " is composite");
        }
    }
}

